def insertion_point(xs, x):
    """Return the leftmost index at which x could be inserted into the
    sorted list xs to keep it sorted (same contract as bisect.bisect_left)."""
    lo, hi = 0, len(xs)
    while lo < hi:
        mid = (lo + hi) // 2
        if xs[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo
